#include <iostream>
#include <vector>

int main() {
    int count, sum;
    std::cin >> count >> sum;
    std::vector<int> numbers(count);
    for (int &number : numbers) std::cin >> number;

    // 先固定右端点，再从近到远查找左端点。
    for (int right = 1; right < count; ++right) {
        for (int left = right - 1; left >= 0; --left) {
            if (numbers[left] + numbers[right] != sum) continue;
            std::cout << left << " " << right << std::endl;
            return 0;
        }
    }
    std::cout << "-1 -1" << std::endl;
}

#include <iostream>
#include <map>
#include <utility>
#include <vector>

std::pair<int, int> locatePair(const std::vector<int>& data, int goal) {
    std::map<int, int> positions;
    for (int end = 0; end < static_cast<int>(data.size()); ++end) {
        const int missing = goal - data[end];
        if (positions.count(missing) != 0) {
            return {positions.at(missing), end};
        }
        positions[data[end]] = end;
    }
    return {-1, -1};
}

int main() {
    int length, goal;
    std::cin >> length >> goal;
    std::vector<int> data(length);
    for (auto& item : data) std::cin >> item;
    const auto answer = locatePair(data, goal);
    std::cout << answer.first << ' ' << answer.second << '\n';
}

#include <iostream>
#include <unordered_map>

int main() {
    int size, goal;
    std::cin >> size >> goal;
    std::unordered_map<int, int> index;
    for (int position = 0; position < size; ++position) {
        int current;
        std::cin >> current;
        index[current] = position;
        const auto found = index.find(goal - current);
        if (found != index.end()) {
            std::cout << found->second << ' ' << position << '\n';
            return 0;
        }
    }
    std::cout << "-1 -1\n";
}

#include <iostream>
#include <vector>

int main() {
    int n, target;
    std::cin >> n >> target;
    std::vector<int> values(n);
    for (int i = 0; i < n; ++i) std::cin >> values[i];
    for (int j = 1; j < n; ++j) {
        int i = j - 1;
        while (i >= 0) {
            if (values[i] + values[j] == target) {
                std::cout << i << " " << j << "\n";
                return 0;
            }
            --i;
        }
    }
    return 0;
}

#include <iostream>
#include <unordered_map>
