int main() {
    int n, goal;
    if (!(cin >> n >> goal)) return 0;
    unordered_map<int, int> lookup;
    for (int i = 0; i < n; ++i) {
        int number;
        cin >> number;
        auto found = lookup.find(goal - number);
        if (found != lookup.end()) {
            cout << found->second << ' ' << i << '\n';
            return 0;
        }
        lookup[number] = i;
    }
    cout << -1 << ' ' << -1 << '\n';
}
